// Signature — question templates, Phase 1 (Foundation) and Phase 2 (Combine & Transform).
(function () {
  const { G, util } = window.SIG.GEN;
  const { money, list, q, monthRange } = util;

  // ───────── d01 · Tables & Keys
  const PEEK = ['hr.Employees', 'catalog.Products', 'crm.Customers'];
  const PEEK2 = ['sales.Returns', 'sales.MonthlyTargets', 'support.Tickets'];
  G('d01', 1, { p: r => ({ t: r.pick(PEEK) }), ask: p => `I’ve never looked inside ${p.t}. Show me everything in it, so I can see how it’s laid out.`, clue: () => 'everything in it', sol: p => `SELECT *\nFROM ${p.t};`, need: ['d01'] });
  G('d01', 2, { p: r => r.pick([{ c: ['TABLE_SCHEMA', 'TABLE_NAME'], w: 'each table’s schema and name' }, { c: ['TABLE_NAME', 'TABLE_TYPE'], w: 'each table’s name and whether it’s a table or a view' }, { c: ['TABLE_SCHEMA', 'TABLE_NAME', 'TABLE_TYPE'], w: 'each one’s schema, name and type' }]),
    ask: p => `Which tables live in CelestiaRetailLab? Show ${p.w}.`, clue: () => 'Which tables live in CelestiaRetailLab', sol: p => `SELECT ${p.c.join(', ')}\nFROM INFORMATION_SCHEMA.TABLES;`,
    why: () => 'This is a question about the database itself. SQL Server keeps that list in INFORMATION_SCHEMA.TABLES.', need: ['d01'] });
  G('d01', 3, { p: r => r.pick([{ c: ['TABLE_NAME', 'COLUMN_NAME'], w: 'every column, with the table it belongs to' }, { c: ['COLUMN_NAME', 'DATA_TYPE'], w: 'every column and its data type' }, { c: ['TABLE_NAME', 'COLUMN_NAME', 'DATA_TYPE'], w: 'every column with its table and data type' }]),
    ask: p => `For our data dictionary, list ${p.w}.`, clue: p => p.w, sol: p => `SELECT ${p.c.join(', ')}\nFROM INFORMATION_SCHEMA.COLUMNS;`,
    why: () => 'Columns and types are about structure. INFORMATION_SCHEMA.COLUMNS describes every column.', need: ['d01'] });
  G('d01', 4, { p: r => ({ t: r.pick(PEEK2) }), ask: p => `What does one row of ${p.t} stand for? Show me the whole table so I can read a few rows.`, clue: () => 'Show me the whole table', sol: p => `SELECT *\nFROM ${p.t};`, need: ['d01'] });
  G('d01', 5, { ask: () => 'I’m writing a data dictionary. For every column, show its schema, table, column name, data type and whether it can be left empty.', clue: () => 'whether it can be left empty',
    sol: () => `SELECT TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME, DATA_TYPE, IS_NULLABLE\nFROM INFORMATION_SCHEMA.COLUMNS;`, why: () => '“Can be left empty” is IS_NULLABLE, one of the columns INFORMATION_SCHEMA.COLUMNS keeps for you.', need: ['d01'], fixed: true });

  // ───────── d02 · SELECT & FROM
  const PICKS = [
    { t: 'crm.Customers', c: ['CustomerName', 'City'], w: 'name and city' }, { t: 'crm.Customers', c: ['CustomerName', 'Email'], w: 'name and email' },
    { t: 'crm.Customers', c: ['CustomerName', 'StateCode', 'JoinDate'], w: 'name, state and the date they joined' }, { t: 'catalog.Products', c: ['ProductName', 'UnitPrice'], w: 'product name and price' },
    { t: 'catalog.Products', c: ['ProductName', 'Category'], w: 'product name and category' }, { t: 'hr.Employees', c: ['EmployeeName', 'Department'], w: 'name and department' },
    { t: 'hr.Employees', c: ['EmployeeName', 'Region', 'HireDate'], w: 'name, region and hire date' }, { t: 'sales.Returns', c: ['OrderID', 'ReturnReason', 'RefundAmount'], w: 'order ID, reason and refund amount' }];
  const WHO = { 'crm.Customers': 'our customers', 'catalog.Products': 'our products', 'hr.Employees': 'our team', 'sales.Returns': 'our returns' };
  G('d02', 1, { p: r => r.pick(PICKS), ask: p => `Give me a list of ${WHO[p.t]}: just the ${p.w}.`, clue: p => `just the ${p.w}`, sol: p => `SELECT ${p.c.join(', ')}\nFROM ${p.t};`, ok: ['d01'] });
  G('d02', 2, { p: r => r.pick(PICKS), ask: p => `Please send me the ${p.w} from ${p.t}. Not every column, just those.`, clue: p => 'Not every column, just those', sol: p => `SELECT ${p.c.join(', ')}\nFROM ${p.t};`, ok: ['d01'] });
  const HEAD = [{ t: 'hr.Employees', c: ['EmployeeName', 'Department'], h: ['Employee', 'Team'] }, { t: 'crm.Customers', c: ['CustomerName', 'CustomerSegment'], h: ['Customer', 'Segment'] }, { t: 'catalog.Products', c: ['ProductName', 'UnitPrice'], h: ['Item', 'Price'] }, { t: 'sales.Returns', c: ['ReturnDate', 'ReturnReason'], h: ['Returned On', 'Reason'] }];
  G('d02', 3, { p: r => r.pick(HEAD), ask: p => `From ${p.t}, send me ${p.c.join(' and ')}, with the headers called ${p.h[0]} and ${p.h[1]}.`, clue: p => `headers called ${p.h[0]} and ${p.h[1]}`,
    sol: p => `SELECT ${p.c[0]} AS ${/ /.test(p.h[0]) ? `[${p.h[0]}]` : p.h[0]},\n       ${p.c[1]} AS ${p.h[1]}\nFROM ${p.t};`, why: () => '“Headers called …” means renaming the columns with AS.', ok: ['d01'] });
  G('d02', 4, { p: r => ({ pct: r.pick([5, 8, 10, 20]) }), ask: p => `Show each product’s name, its price, and what it would cost with ${p.pct}% tax added.`, clue: p => `with ${p.pct}% tax added`,
    sol: p => `SELECT ProductName, UnitPrice,\n       UnitPrice * ${(1 + p.pct / 100).toFixed(2)} AS PriceWithTax\nFROM catalog.Products;`, why: () => 'A new column worked out from an existing one is a calculation right in the SELECT list.', ok: ['d01'] });
  G('d02', 5, { p: r => ({ v: r.pick(['margin', 'profit']) }), ask: p => `I’m pricing up the catalog. For every product: name, category, price, cost, and the ${p.v} on one unit (price minus cost).`, clue: p => `the ${p.v} on one unit (price minus cost)`,
    sol: () => `SELECT ProductName, Category, UnitPrice, UnitCost,\n       UnitPrice - UnitCost AS Margin\nFROM catalog.Products;`, ok: ['d01'] });

  // ───────── d03a · DISTINCT
  const ONE = [{ t: 'catalog.Products', c: 'Category', w: 'product categories do we sell' }, { t: 'crm.Customers', c: 'City', w: 'cities do our customers live in' }, { t: 'crm.Customers', c: 'CustomerSegment', w: 'customer segments do we use' }, { t: 'sales.Orders', c: 'Channel', w: 'sales channels do orders come through' }, { t: 'hr.Employees', c: 'Department', w: 'departments do we have' }, { t: 'sales.Returns', c: 'ReturnReason', w: 'reasons have customers given for returns' }, { t: 'sales.Orders', c: 'Status', w: 'order statuses are in use' }];
  G('d03a', 1, { p: r => r.pick(ONE), ask: p => `Which ${p.w}? Just the list, no repeats.`, clue: () => 'no repeats', sol: p => `SELECT DISTINCT ${p.c}\nFROM ${p.t};`, ok: ['d02'], distract: ['d16b', 'd06'] });
  const TWO = [{ t: 'crm.Customers', c: ['City', 'StateCode'], w: 'city and state pair' }, { t: 'hr.Employees', c: ['Department', 'Region'], w: 'department and region pair' }, { t: 'sales.Orders', c: ['Channel', 'Priority'], w: 'channel and priority pair' }, { t: 'support.Tickets', c: ['ContactChannel', 'Priority'], w: 'contact channel and priority pair on our tickets' }];
  G('d03a', 2, { p: r => r.pick(TWO), ask: p => `List each ${p.w} once.`, clue: p => 'once', sol: p => `SELECT DISTINCT ${p.c.join(', ')}\nFROM ${p.t};`, ok: ['d02'] });
  G('d03a', 3, { p: r => r.pick([{ c: 'CustomerID', t: 'sales.Orders', w: 'customers have placed an order? Just their customer IDs' }, { c: 'ProductID', t: 'sales.OrderItems', w: 'products have ever been sold? Just the product IDs' }, { c: 'EmployeeID', t: 'sales.Orders', w: 'employees have taken an order? Just their employee IDs' }, { c: 'ProductID', t: 'sales.Returns', w: 'products have been returned at least once? Just the product IDs' }]),
    ask: p => `Which ${p.w}, each one once.`, clue: () => 'each one once', sol: p => `SELECT DISTINCT ${p.c}\nFROM ${p.t};`, ok: ['d02'] });
  G('d03a', 4, { p: r => r.pick([{ a: 'CustomerSegment', b: 'Category', w: 'customer segment and product category' }, { a: 'Channel', b: 'Category', w: 'sales channel and product category' }, { a: 'CustomerSegment', b: 'Channel', w: 'customer segment and channel' }]),
    ask: p => `Using the sales detail view, which ${p.w} combinations actually happen? One row per combination, with headers called ${p.a === 'CustomerSegment' ? 'Segment' : p.a} and ${p.b}.`, clue: () => 'One row per combination',
    sol: p => `SELECT DISTINCT ${p.a} AS ${p.a === 'CustomerSegment' ? 'Segment' : p.a}, ${p.b}\nFROM reporting.vSalesLineDetail;`, ok: ['d02'] });
  G('d03a', 5, { p: r => r.pick([{ c: ['CustomerID', 'Channel'], w: 'Which channels has each customer used? One row per customer-and-channel pair' }, { c: ['OrderID', 'ReturnReason'], w: 'For each order with a return, which reasons were given? One row per order-and-reason pair' }, { c: ['CustomerID', 'ContactChannel'], w: 'How has each customer contacted support? One row per customer-and-channel pair' }]),
    ask: p => `${p.w}.`, clue: () => 'One row per', sol: p => `SELECT DISTINCT ${p.c.join(', ')}\nFROM ${p.c[1] === 'ReturnReason' ? 'sales.Returns' : p.c[1] === 'ContactChannel' ? 'support.Tickets' : 'sales.Orders'};`, ok: ['d02'] });

  // ───────── d03b · ORDER BY & TOP
  G('d03b', 1, { p: r => ({ n: r.int(3, 7), dir: r.pick(['most expensive', 'cheapest']) }), ask: p => `Show me the ${p.n} ${p.dir} products, with their prices.`, clue: p => `${p.n} ${p.dir}`,
    sol: p => `SELECT TOP (${p.n}) ProductName, UnitPrice\nFROM catalog.Products\nORDER BY UnitPrice${p.dir === 'cheapest' ? '' : ' DESC'};`, ok: ['d02'] });
  G('d03b', 2, { p: r => r.pick([{ c: 'EmployeeName, HireDate', t: 'hr.Employees', o: 'HireDate', w: 'every employee by hire date, earliest first' }, { c: 'CustomerName, JoinDate', t: 'crm.Customers', o: 'JoinDate DESC', w: 'every customer by the date they joined, newest first' }, { c: 'ProductName, Category', t: 'catalog.Products', o: 'ProductName', w: 'every product, A to Z by name' }, { c: 'EmployeeName, Department', t: 'hr.Employees', o: 'EmployeeName', w: 'the team, A to Z by name' }]),
    ask: p => `List ${p.w}.`, clue: p => p.w.split(', ').pop(), sol: p => `SELECT ${p.c}\nFROM ${p.t}\nORDER BY ${p.o};`, ok: ['d02'] });
  G('d03b', 3, { p: r => r.pick([{ c: 'City', t: 'crm.Customers', w: 'every city we have a customer in' }, { c: 'Category', t: 'catalog.Products', w: 'our product categories' }, { c: 'Region', t: 'hr.Employees', w: 'the regions our team covers' }]),
    ask: p => `List ${p.w}, each once, A to Z.`, clue: () => 'each once, A to Z', sol: p => `SELECT DISTINCT ${p.c}\nFROM ${p.t}\nORDER BY ${p.c};`, need: ['d03b', 'd03a'], ok: ['d02'] });
  G('d03b', 4, { p: r => ({ n: r.int(3, 6) }), ask: p => `Which ${p.n} products make us the most on each sale? Show name and margin (price minus cost), biggest first.`, clue: p => `${p.n} products make us the most`,
    sol: p => `SELECT TOP (${p.n}) ProductName,\n       UnitPrice - UnitCost AS Margin\nFROM catalog.Products\nORDER BY Margin DESC;`, ok: ['d02'] });
  G('d03b', 5, { p: r => ({ n: r.pick([8, 10, 12]) }), ask: p => `Show our ${p.n} most recent orders: ID, date and channel, newest first. If two share a date, show the higher order ID first.`, clue: p => `${p.n} most recent`,
    sol: p => `SELECT TOP (${p.n}) OrderID, OrderDate, Channel\nFROM sales.Orders\nORDER BY OrderDate DESC, OrderID DESC;`, ok: ['d02'] });

  // ───────── d04 · CREATE · ALTER · DROP
  const DESIGNS = [
    { n: 'Wishlist', say: 'a wish list: WishlistID (a whole number and the primary key), CustomerID and ProductID (whole numbers, required), and AddedOn (a date, required)', cols: 'WishlistID INT PRIMARY KEY,\n  CustomerID INT NOT NULL,\n  ProductID  INT NOT NULL,\n  AddedOn    DATE NOT NULL' },
    { n: 'StoreVisits', say: 'store foot traffic: VisitID (whole number, primary key), StoreCity (text up to 60 characters, required), VisitDate (date, required) and Visitors (whole number, required)', cols: 'VisitID   INT PRIMARY KEY,\n  StoreCity NVARCHAR(60) NOT NULL,\n  VisitDate DATE NOT NULL,\n  Visitors  INT NOT NULL' },
    { n: 'Suppliers', say: 'our suppliers: SupplierID (whole number, primary key), SupplierName (text up to 100, required), Country (text up to 40, required) and Phone (text up to 20, optional)', cols: 'SupplierID   INT PRIMARY KEY,\n  SupplierName NVARCHAR(100) NOT NULL,\n  Country      VARCHAR(40) NOT NULL,\n  Phone        VARCHAR(20) NULL' },
    { n: 'GiftCards', say: 'gift cards: CardID (whole number, primary key), CustomerID (whole number, required), Balance (money with 2 decimals, required) and ExpiresOn (date, optional)', cols: 'CardID     INT PRIMARY KEY,\n  CustomerID INT NOT NULL,\n  Balance    DECIMAL(10,2) NOT NULL,\n  ExpiresOn  DATE NULL' }];
  const mk = d => `CREATE TABLE dbo.${d.n} (\n  ${d.cols}\n);`;
  G('d04', 1, { p: r => r.pick(DESIGNS), ask: p => `Create a table called dbo.${p.n} for ${p.say}.`, clue: p => `Create a table called dbo.${p.n}`, sol: p => mk(p), checks: p => [{ kind: 'table', name: p.n, show: 'dbo.' + p.n }] });
  G('d04', 2, { p: r => r.pick(DESIGNS), ask: p => `We need somewhere to keep ${p.say}. Please set up dbo.${p.n}.`, clue: p => `set up dbo.${p.n}`, sol: p => mk(p), checks: p => [{ kind: 'table', name: p.n, show: 'dbo.' + p.n }] });
  const ADDS = [{ d: 0, c: 'Notes NVARCHAR(200) NULL', w: 'an optional Notes column (text up to 200 characters)' }, { d: 1, c: 'WeatherNote VARCHAR(50) NULL', w: 'an optional WeatherNote column (text up to 50)' }, { d: 2, c: 'Website VARCHAR(120) NULL', w: 'an optional Website column (text up to 120)' }, { d: 3, c: 'IsActive BIT NOT NULL DEFAULT 1', w: 'an IsActive yes/no column that is required and starts as 1' }];
  G('d04', 3, { p: r => { const a = r.pick(ADDS); return Object.assign({ a }, DESIGNS[a.d]); }, before: p => mk(p), ask: p => `dbo.${p.n} already exists. Add ${p.a.w}, without losing the table.`, clue: p => 'without losing the table',
    sol: p => `ALTER TABLE dbo.${p.n}\nADD ${p.a.c};`, checks: p => [{ kind: 'table', name: p.n, show: 'dbo.' + p.n }], why: () => '“Without losing the table” means changing it in place with ALTER TABLE, not dropping it.' });
  G('d04', 4, { p: r => r.pick([{ d: 0, x: 'TempFlag', xt: 'BIT NULL' }, { d: 1, x: 'OldCode', xt: 'VARCHAR(10) NULL' }, { d: 2, x: 'FaxNumber', xt: 'VARCHAR(20) NULL' }]), before: p => { const d = DESIGNS[p.d]; return `CREATE TABLE dbo.${d.n} (\n  ${d.cols},\n  ${p.x} ${p.xt}\n);`; },
    ask: p => `dbo.${DESIGNS[p.d].n} has a ${p.x} column nobody uses any more. Remove that column and keep everything else.`, clue: p => `Remove that column`,
    sol: p => `ALTER TABLE dbo.${DESIGNS[p.d].n}\nDROP COLUMN ${p.x};`, checks: p => [{ kind: 'table', name: DESIGNS[p.d].n, show: 'dbo.' + DESIGNS[p.d].n }] });
  G('d04', 5, { p: r => r.pick(DESIGNS), before: p => `CREATE TABLE dbo.${p.n} (Placeholder INT);`, ask: p => `Someone made a broken dbo.${p.n} table. Throw it away and build it again properly, for ${p.say}. Write it so it would also work if the old table weren’t there.`, clue: p => 'also work if the old table weren’t there',
    sol: p => `DROP TABLE IF EXISTS dbo.${p.n};\n${mk(p)}`, checks: p => [{ kind: 'table', name: p.n, show: 'dbo.' + p.n }], why: () => '“Would also work if it weren’t there” is DROP TABLE IF EXISTS.' });

  // ───────── d05 · INSERT · UPDATE · DELETE
  const NEWP = [['Linen Desk Pad', 'Stationery', 26, 10.4], ['Glass Pen Set', 'Stationery', 34, 13.6], ['Ceramic Pour Jug', 'Drinkware', 44, 17], ['Pocket Sketchbook', 'Art', 15, 5.5], ['Magnetic Cable Dock', 'Tech', 29, 12]];
  G('d05', 1, { p: r => ({ x: r.pick(NEWP) }), ask: p => `We’re launching “${p.x[0]}” (${p.x[1]}) today, 30 June 2025, as product 126. Price ${money(p.x[2])}, cost ${money(p.x[3])}, and it’s active. Please add it.`, clue: () => 'Please add it',
    sol: p => `INSERT INTO catalog.Products (ProductID, ProductName, Category, UnitPrice, UnitCost, IsActive, LaunchDate)\nVALUES (126, ${q(p.x[0])}, ${q(p.x[1])}, ${p.x[2]}, ${p.x[3]}, 1, '2025-06-30');`, checks: () => [{ kind: 'rows', sql: 'SELECT * FROM catalog.Products' }] });
  G('d05', 2, { p: (r, d) => { const pr = r.pick(d.products); return { id: pr.id, name: pr.name, price: Math.round(pr.price * r.pick([1.1, 1.2, 0.9])) }; }, ask: p => `The price of ${p.name} (product ${p.id}) is changing to ${money(p.price)}. Please update it, and only that product.`, clue: () => 'only that product',
    sol: p => `UPDATE catalog.Products\nSET UnitPrice = ${p.price}\nWHERE ProductID = ${p.id};`, checks: () => [{ kind: 'rows', sql: 'SELECT * FROM catalog.Products' }], why: () => 'Changing an existing row is UPDATE, and “only that product” means WHERE on its key.' });
  G('d05', 3, { p: (r, d) => ({ c: r.pick(d.buyers), ps: r.some(d.products, 2) }), before: () => mk(DESIGNS[0]), ask: p => `Customer ${p.c} wants two items on their wish list: products ${p.ps[0].id} and ${p.ps[1].id}. Add them to dbo.Wishlist as entries 1 and 2, added today (30 June 2025).`, clue: () => 'Add them',
    sol: p => `INSERT INTO dbo.Wishlist (WishlistID, CustomerID, ProductID, AddedOn)\nVALUES (1, ${p.c}, ${p.ps[0].id}, '2025-06-30'),\n       (2, ${p.c}, ${p.ps[1].id}, '2025-06-30');`, checks: () => [{ kind: 'rows', sql: 'SELECT * FROM Wishlist' }], ok: ['d04'] });
  G('d05', 4, { p: r => ({ id: r.int(6, 42) }), ask: p => `Return ${p.id} was logged by mistake. Please remove it, and nothing else.`, clue: () => 'remove it, and nothing else', sol: p => `DELETE FROM sales.Returns\nWHERE ReturnID = ${p.id};`, checks: () => [{ kind: 'rows', sql: 'SELECT * FROM sales.Returns' }] });
  G('d05', 5, { p: r => r.pick([{ cols: 'ProductID, ProductName, UnitPrice', t: 'PriceList', def: 'ProductID INT PRIMARY KEY, ProductName NVARCHAR(100), UnitPrice DECIMAL(10,2)', w: 'every product’s ID, name and price' }, { cols: 'CustomerID, CustomerName, Email', t: 'MailingList', def: 'CustomerID INT PRIMARY KEY, CustomerName NVARCHAR(100), Email NVARCHAR(120)', w: 'every customer’s ID, name and email' }]),
    before: p => `CREATE TABLE dbo.${p.t} (${p.def});`, ask: p => `dbo.${p.t} is empty. Fill it with ${p.w}, copied straight from the main tables, in one statement.`, clue: () => 'copied straight from the main tables',
    sol: p => `INSERT INTO dbo.${p.t} (${p.cols})\nSELECT ${p.cols}\nFROM ${p.t === 'PriceList' ? 'catalog.Products' : 'crm.Customers'};`, checks: p => [{ kind: 'rows', sql: `SELECT * FROM ${p.t}` }], ok: ['d04', 'd02'], why: () => '“Copied from the main tables” is INSERT … SELECT: the rows come from a query instead of typed-in VALUES.' });

  // ───────── d06 · WHERE · AND · OR
  G('d06', 1, { p: (r, d) => r.pick([{ k: 'city', v: r.pick(d.cities) }, { k: 'cat', v: r.pick(d.categories) }, { k: 'dept', v: r.pick(d.depts) }, { k: 'seg', v: r.pick(d.segments) }]),
    ask: p => ({ city: `Which customers live in ${p.v}? Just their names and emails.`, cat: `Show me just the ${p.v} products, with their prices.`, dept: `Who works in ${p.v}? Names and regions, please.`, seg: `List our ${p.v} customers: name and city.` })[p.k],
    clue: p => ({ city: `live in ${p.v}`, cat: `just the ${p.v} products`, dept: `works in ${p.v}`, seg: `our ${p.v} customers` })[p.k],
    sol: p => ({ city: `SELECT CustomerName, Email\nFROM crm.Customers\nWHERE City = ${q(p.v)};`, cat: `SELECT ProductName, UnitPrice\nFROM catalog.Products\nWHERE Category = ${q(p.v)};`, dept: `SELECT EmployeeName, Region\nFROM hr.Employees\nWHERE Department = ${q(p.v)};`, seg: `SELECT CustomerName, City\nFROM crm.Customers\nWHERE CustomerSegment = ${q(p.v)};` })[p.k], ok: ['d02'] });
  G('d06', 2, { p: r => r.pick([{ k: 'over', n: r.pick([40, 45, 50, 60]) }, { k: 'under', n: r.pick([15, 20, 25]) }, { k: 'ref', n: r.pick([40, 50, 60]) }]),
    ask: p => ({ over: `Which products cost more than ${money(p.n)}? Name and price.`, under: `Which products cost under ${money(p.n)}? Name and price.`, ref: `Which returns refunded at least ${money(p.n)}? Return ID, order ID and amount.` })[p.k],
    clue: p => ({ over: `more than ${money(p.n)}`, under: `under ${money(p.n)}`, ref: `at least ${money(p.n)}` })[p.k],
    sol: p => ({ over: `SELECT ProductName, UnitPrice\nFROM catalog.Products\nWHERE UnitPrice > ${p.n};`, under: `SELECT ProductName, UnitPrice\nFROM catalog.Products\nWHERE UnitPrice < ${p.n};`, ref: `SELECT ReturnID, OrderID, RefundAmount\nFROM sales.Returns\nWHERE RefundAmount >= ${p.n};` })[p.k], ok: ['d02'] });
  G('d06', 3, { p: (r, d) => ({ ch: r.pick(d.channels), st: r.pick(['Cancelled', 'Delivered']), n: r.pick([5, 8, 10]) }), ask: p => `Show the ${p.n} most recent ${p.ch} orders that were ${p.st.toLowerCase()}: order ID and date, newest first. If dates tie, higher ID first.`, clue: p => `${p.ch} orders that were ${p.st.toLowerCase()}`,
    sol: p => `SELECT TOP (${p.n}) OrderID, OrderDate\nFROM sales.Orders\nWHERE Channel = ${q(p.ch)}\n  AND Status = ${q(p.st)}\nORDER BY OrderDate DESC, OrderID DESC;`, need: ['d06', 'd03b'], ok: ['d02'] });
  G('d06', 4, { p: (r, d) => { const c = r.some(d.categories, 2); return { a: c[0], b: c[1], n: r.pick([25, 30, 35, 40]) }; }, ask: p => `I want ${p.a} or ${p.b} products that cost under ${money(p.n)}. Name, category and price.`, clue: p => `${p.a} or ${p.b} products that cost under ${money(p.n)}`,
    sol: p => `SELECT ProductName, Category, UnitPrice\nFROM catalog.Products\nWHERE (Category = ${q(p.a)} OR Category = ${q(p.b)})\n  AND UnitPrice < ${p.n};`, why: () => 'Mixing OR with AND needs brackets around the OR part, or SQL Server applies AND first.', ok: ['d02'] });
  G('d06', 5, { p: (r, d) => ({ city: r.pick(d.cities) }), ask: p => `For a thank-you mailing in ${p.city}: active customers there who are VIP or Loyal. Name and segment, A to Z by name.`, clue: p => ['active customers', 'VIP or Loyal'],
    sol: p => `SELECT CustomerName, CustomerSegment\nFROM crm.Customers\nWHERE City = ${q(p.city)}\n  AND IsActive = 1\n  AND (CustomerSegment = 'VIP' OR CustomerSegment = 'Loyal')\nORDER BY CustomerName;`, need: ['d06', 'd03b'], ok: ['d02'] });

  // ───────── d07 · BETWEEN · IN · LIKE · IS NULL
  G('d07', 1, { p: (r, d) => { const m = r.pick(d.months); const a = r.int(1, 15); return { m, a, b: a + r.int(4, 9) }; }, ask: p => `Which orders were placed between ${p.m.mon} ${p.a} and ${p.m.mon} ${p.b}, ${p.m.y}, inclusive? Order ID and date.`, clue: p => `between ${p.m.mon} ${p.a} and ${p.m.mon} ${p.b}`,
    sol: p => `SELECT OrderID, OrderDate\nFROM sales.Orders\nWHERE OrderDate BETWEEN '${p.m.y}-${util.pad(p.m.m)}-${util.pad(p.a)}' AND '${p.m.y}-${util.pad(p.m.m)}-${util.pad(p.b)}';`, ok: ['d02', 'd06'] });
  G('d07', 2, { p: r => r.pick([{ k: 'start', v: r.pick(['A', 'C', 'E', 'L', 'M', 'N', 'S']) }, { k: 'word', v: r.pick(['Set', 'Journal', 'Pen', 'Kit', 'Tray', 'Cup']) }]),
    ask: p => (p.k === 'start' ? `Which customers have a name starting with “${p.v}”? Names only.` : `Which products have “${p.v}” anywhere in the name? Name and price.`), clue: p => (p.k === 'start' ? `starting with “${p.v}”` : `“${p.v}” anywhere in the name`),
    sol: p => (p.k === 'start' ? `SELECT CustomerName\nFROM crm.Customers\nWHERE CustomerName LIKE '${p.v}%';` : `SELECT ProductName, UnitPrice\nFROM catalog.Products\nWHERE ProductName LIKE '%${p.v}%';`), ok: ['d02', 'd06'] });
  G('d07', 3, { p: r => r.pick([{ c: 'Email', w: 'no email address on file' }, { c: 'Phone', w: 'no phone number on file' }]), ask: p => `Who has ${p.w}? Name and city, A to Z by name.`, clue: p => p.w,
    sol: p => `SELECT CustomerName, City\nFROM crm.Customers\nWHERE ${p.c} IS NULL\nORDER BY CustomerName;`, need: ['d07', 'd03b'], ok: ['d02', 'd06'] });
  G('d07', 4, { p: (r, d) => ({ cities: r.some(d.cities, 3) }), ask: p => `List the customers in ${list(p.cities)}: name, city and segment, sorted by city then name.`, clue: p => `in ${list(p.cities)}`,
    sol: p => `SELECT CustomerName, City, CustomerSegment\nFROM crm.Customers\nWHERE City IN (${p.cities.map(q).join(', ')})\nORDER BY City, CustomerName;`, need: ['d07', 'd03b'], ok: ['d02', 'd06'] });
  G('d07', 5, { p: (r, d) => ({ m: r.pick(d.months), chs: r.some(d.channels, 2) }), ask: p => `${p.chs.join(' and ')} orders from ${p.m.name} that got no discount at all. Order ID, date and channel, oldest first (lower ID first on the same day).`, clue: p => ['got no discount at all', `${p.chs.join(' and ')} orders`],
    sol: p => `SELECT OrderID, OrderDate, Channel\nFROM sales.Orders\nWHERE OrderDate BETWEEN '${p.m.start}' AND '${p.m.last}'\n  AND Channel IN (${p.chs.map(q).join(', ')})\n  AND DiscountAmount IS NULL\nORDER BY OrderDate, OrderID;`, need: ['d07', 'd03b'], ok: ['d02', 'd06'] });

  // ───────── d08 · INNER JOIN
  G('d08', 1, { p: r => r.pick([{ k: 'oc' }, { k: 'ip' }, { k: 'oe' }]), ask: p => ({ oc: 'List every order with the customer’s name: order ID, order date and customer name.', ip: 'List every order line with the product’s name: order ID, product name and quantity.', oe: 'For every order, show the order ID and the name of the employee who took it.' })[p.k],
    clue: p => ({ oc: 'with the customer’s name', ip: 'with the product’s name', oe: 'the name of the employee' })[p.k],
    sol: p => ({ oc: `SELECT o.OrderID, o.OrderDate, c.CustomerName\nFROM sales.Orders o\nINNER JOIN crm.Customers c ON c.CustomerID = o.CustomerID;`, ip: `SELECT i.OrderID, p.ProductName, i.Quantity\nFROM sales.OrderItems i\nINNER JOIN catalog.Products p ON p.ProductID = i.ProductID;`, oe: `SELECT o.OrderID, e.EmployeeName\nFROM sales.Orders o\nINNER JOIN hr.Employees e ON e.EmployeeID = o.EmployeeID;` })[p.k], ok: ['d02'] });
  G('d08', 2, { p: r => r.pick([{ k: 'rp' }, { k: 'tc' }]), ask: p => (p.k === 'rp' ? 'For each return, show the return date, the product’s name and the refund amount.' : 'For each support ticket, show the ticket ID, its status and the customer’s name.'), clue: p => (p.k === 'rp' ? 'the product’s name' : 'the customer’s name'),
    sol: p => (p.k === 'rp' ? `SELECT r.ReturnDate, p.ProductName, r.RefundAmount\nFROM sales.Returns r\nINNER JOIN catalog.Products p ON p.ProductID = r.ProductID;` : `SELECT t.TicketID, t.Status, c.CustomerName\nFROM support.Tickets t\nINNER JOIN crm.Customers c ON c.CustomerID = t.CustomerID;`), ok: ['d02'] });
  G('d08', 3, { p: (r, d) => ({ city: r.pick(d.cities), ch: r.pick(d.channels) }), ask: p => `Show the ${p.ch} orders placed by customers in ${p.city}: order ID, date and customer name, oldest first (lower ID first on the same day).`, clue: p => `customers in ${p.city}`,
    sol: p => `SELECT o.OrderID, o.OrderDate, c.CustomerName\nFROM sales.Orders o\nINNER JOIN crm.Customers c ON c.CustomerID = o.CustomerID\nWHERE c.City = ${q(p.city)}\n  AND o.Channel = ${q(p.ch)}\nORDER BY o.OrderDate, o.OrderID;`, need: ['d08', 'd06', 'd03b'], ok: ['d02'] });
  G('d08', 4, { p: (r, d) => ({ cat: r.pick(d.categories), n: r.pick([3, 5]) }), ask: p => `Which ${p.n} ${p.cat} products have been returned for the biggest single refunds? Product name, return date and refund, biggest first. If refunds tie, earliest return first.`, clue: p => `${p.cat} products`,
    sol: p => `SELECT TOP (${p.n}) p.ProductName, r.ReturnDate, r.RefundAmount\nFROM sales.Returns r\nINNER JOIN catalog.Products p ON p.ProductID = r.ProductID\nWHERE p.Category = ${q(p.cat)}\nORDER BY r.RefundAmount DESC, r.ReturnDate;`, need: ['d08', 'd06', 'd03b'], ok: ['d02'] });
  G('d08', 5, { p: (r, d) => ({ m: r.pick(d.months25), ch: r.pick(d.channels) }), ask: p => `For ${p.ch} orders in ${p.m.name}, show who bought what: customer name, product name and quantity, sorted by customer then product.`, clue: p => 'who bought what',
    sol: p => `SELECT c.CustomerName, p.ProductName, i.Quantity\nFROM sales.Orders o\nINNER JOIN crm.Customers c ON c.CustomerID = o.CustomerID\nINNER JOIN sales.OrderItems i ON i.OrderID = o.OrderID\nINNER JOIN catalog.Products p ON p.ProductID = i.ProductID\nWHERE o.Channel = ${q(p.ch)}\n  AND o.OrderDate >= '${p.m.start}' AND o.OrderDate < '${p.m.next}'\nORDER BY c.CustomerName, p.ProductName;`, need: ['d08', 'd06', 'd03b'], ok: ['d02', 'd07'], why: () => '“Who bought what” needs four tables: customers, orders, order lines and products, chained by their keys.' });

  // ───────── d09 · LEFT JOIN & multi-table
  G('d09', 1, { p: r => r.pick([{ k: 'co' }, { k: 'pr' }]), ask: p => (p.k === 'co' ? 'List every customer with the IDs of any orders they’ve placed. Customers with no orders should still appear.' : 'List every product with the IDs of any returns made for it. Products that were never returned should still appear.'), clue: p => 'should still appear',
    sol: p => (p.k === 'co' ? `SELECT c.CustomerName, o.OrderID\nFROM crm.Customers c\nLEFT JOIN sales.Orders o ON o.CustomerID = c.CustomerID;` : `SELECT p.ProductName, r.ReturnID\nFROM catalog.Products p\nLEFT JOIN sales.Returns r ON r.ProductID = p.ProductID;`), ok: ['d02', 'd08'] });
  G('d09', 2, { p: r => r.pick([{ k: 'c', w: 'Which customers have never placed an order? Names only.' }, { k: 'p', w: 'Which products have never been sold? Names only.' }, { k: 'e', w: 'Which employees have never taken an order? Names only.' }]), ask: p => p.w, clue: p => (p.k === 'p' ? 'never been sold' : p.k === 'c' ? 'never placed an order' : 'never taken an order'),
    sol: p => ({ c: `SELECT c.CustomerName\nFROM crm.Customers c\nLEFT JOIN sales.Orders o ON o.CustomerID = c.CustomerID\nWHERE o.OrderID IS NULL;`, p: `SELECT p.ProductName\nFROM catalog.Products p\nLEFT JOIN sales.OrderItems i ON i.ProductID = p.ProductID\nWHERE i.OrderItemID IS NULL;`, e: `SELECT e.EmployeeName\nFROM hr.Employees e\nLEFT JOIN sales.Orders o ON o.EmployeeID = e.EmployeeID\nWHERE o.OrderID IS NULL;` })[p.k], ok: ['d02', 'd06', 'd07'],
    why: () => '“Never” means keeping everyone with a LEFT JOIN, then keeping only the rows where the match came back empty (IS NULL).' });
  G('d09', 3, { p: (r, d) => ({ seg: r.pick(d.segments) }), ask: p => `Which ${p.seg} customers have never opened a support ticket? Name and city, A to Z.`, clue: p => 'never opened a support ticket',
    sol: p => `SELECT c.CustomerName, c.City\nFROM crm.Customers c\nLEFT JOIN support.Tickets t ON t.CustomerID = c.CustomerID\nWHERE t.TicketID IS NULL\n  AND c.CustomerSegment = ${q(p.seg)}\nORDER BY c.CustomerName;`, need: ['d09', 'd06', 'd03b'], ok: ['d02', 'd07'] });
  G('d09', 4, { p: (r, d) => ({ cat: r.pick(d.categories) }), ask: p => `Every ${p.cat} product, with any return reasons recorded for it. Keep products with no returns too. Product name and reason, sorted by product then reason.`, clue: p => 'Keep products with no returns too',
    sol: p => `SELECT p.ProductName, r.ReturnReason\nFROM catalog.Products p\nLEFT JOIN sales.Returns r ON r.ProductID = p.ProductID\nWHERE p.Category = ${q(p.cat)}\nORDER BY p.ProductName, r.ReturnReason;`, need: ['d09', 'd06', 'd03b'], ok: ['d02'] });
  G('d09', 5, { p: (r, d) => ({ city: r.pick(d.cities) }), ask: p => `For our ${p.city} customers, show each one’s orders and, for each order, its return reason if it had one. Include customers with no orders. Customer name, order ID and reason, sorted by name, then order ID.`, clue: p => ['Include customers with no orders', 'if it had one'],
    sol: p => `SELECT c.CustomerName, o.OrderID, r.ReturnReason\nFROM crm.Customers c\nLEFT JOIN sales.Orders o ON o.CustomerID = c.CustomerID\nLEFT JOIN sales.Returns r ON r.OrderID = o.OrderID\nWHERE c.City = ${q(p.city)}\nORDER BY c.CustomerName, o.OrderID;`, need: ['d09', 'd06', 'd03b'], ok: ['d02', 'd08'], ordered: false, why: () => 'Every link in the chain that might be missing needs to be a LEFT JOIN, or the empty rows fall away.' });

  // ───────── d10 · UNION · INTERSECT · EXCEPT
  G('d10', 1, { p: (r, d) => ({ ch: r.pick(d.channels) }), ask: p => `One list of customer IDs: everyone who has placed a ${p.ch} order or opened a support ticket. Each ID once.`, clue: p => `or opened a support ticket`,
    sol: p => `SELECT CustomerID FROM sales.Orders WHERE Channel = ${q(p.ch)}\nUNION\nSELECT CustomerID FROM support.Tickets;`, ok: ['d02', 'd06'] });
  G('d10', 2, { p: r => r.pick([{ k: 'ex' }, { k: 'in' }]), ask: p => (p.k === 'ex' ? 'Which customer IDs have placed orders but never opened a support ticket?' : 'Which customer IDs have both placed an order and opened a support ticket?'), clue: p => (p.k === 'ex' ? 'but never opened' : 'both placed an order and opened'),
    sol: p => `SELECT CustomerID FROM sales.Orders\n${p.k === 'ex' ? 'EXCEPT' : 'INTERSECT'}\nSELECT CustomerID FROM support.Tickets;`, ok: ['d02'] });
  G('d10', 3, { p: (r, d) => { const c = r.some(d.channels, 2); return { a: c[0], b: c[1] }; }, ask: p => `Which customers (by ID) have ordered through both ${p.a} and ${p.b}? Sorted by ID.`, clue: p => `both ${p.a} and ${p.b}`,
    sol: p => `SELECT CustomerID FROM sales.Orders WHERE Channel = ${q(p.a)}\nINTERSECT\nSELECT CustomerID FROM sales.Orders WHERE Channel = ${q(p.b)}\nORDER BY CustomerID;`, need: ['d10', 'd06', 'd03b'], ok: ['d02'] });
  G('d10', 4, { p: (r, d) => ({ city: r.pick(d.cities) }), ask: p => `I’m planning an event and need one guest list of names: every customer in ${p.city}, plus every employee in Sales. Add a second column saying “Customer” or “Employee”. Keep everyone, even if a name appears twice.`, clue: p => ['one guest list', 'Keep everyone, even if a name appears twice'],
    sol: p => `SELECT CustomerName AS Name, 'Customer' AS Kind FROM crm.Customers WHERE City = ${q(p.city)}\nUNION ALL\nSELECT EmployeeName, 'Employee' FROM hr.Employees WHERE Department = 'Sales';`, ok: ['d02', 'd06'] });
  G('d10', 5, { p: (r, d) => ({ a: r.pick(d.months24), b: r.pick(d.months25) }), ask: p => `Which customers ordered in ${p.a.name} but not at all in ${p.b.name}? Customer names, A to Z.`, clue: p => `but not at all in ${p.b.name}`,
    sol: p => `SELECT c.CustomerName\nFROM crm.Customers c\nJOIN sales.Orders o ON o.CustomerID = c.CustomerID\nWHERE o.OrderDate >= '${p.a.start}' AND o.OrderDate < '${p.a.next}'\nEXCEPT\nSELECT c.CustomerName\nFROM crm.Customers c\nJOIN sales.Orders o ON o.CustomerID = c.CustomerID\nWHERE o.OrderDate >= '${p.b.start}' AND o.OrderDate < '${p.b.next}'\nORDER BY CustomerName;`, need: ['d10', 'd08', 'd06'], ok: ['d02', 'd03b', 'd09'] });

  // ───────── d11 · String & Number Functions
  G('d11', 1, { p: r => r.pick([{ k: 'up', w: 'every customer’s name in capital letters' }, { k: 'len', w: 'every product name and how many characters long it is' }, { k: 'left', w: 'every customer’s name and the first 3 letters of their city' }]), ask: p => `Show ${p.w}.`, clue: p => p.w.split(' ').slice(-4).join(' '),
    sol: p => ({ up: `SELECT UPPER(CustomerName) AS NameUpper\nFROM crm.Customers;`, len: `SELECT ProductName, LEN(ProductName) AS NameLength\nFROM catalog.Products;`, left: `SELECT CustomerName, LEFT(City, 3) AS CityCode\nFROM crm.Customers;` })[p.k], ok: ['d02'] });
  G('d11', 2, { p: r => r.pick([{ k: 'nc', ex: 'Amelia Hart (Austin)' }, { k: 'pc', ex: 'Linen Dot Journal – Journals' }]), ask: p => (p.k === 'nc' ? `Make one label per customer that reads like “${p.ex}”: name, space, then the city in brackets.` : `Make one label per product that reads like “${p.ex}”: the name, a space, a dash, a space, then the category.`), clue: p => `reads like “${p.ex}”`,
    sol: p => (p.k === 'nc' ? `SELECT CustomerName + ' (' + City + ')' AS Label\nFROM crm.Customers;` : `SELECT ProductName + ' – ' + Category AS Label\nFROM catalog.Products;`), ok: ['d02'] });
  G('d11', 3, { p: r => ({ n: r.pick([16, 18, 20]) }), ask: p => `Product names longer than ${p.n} characters may not fit on shelf tags. Which ones are they? Name and length, longest first (A to Z if tied).`, clue: p => `longer than ${p.n} characters`,
    sol: p => `SELECT ProductName, LEN(ProductName) AS NameLength\nFROM catalog.Products\nWHERE LEN(ProductName) > ${p.n}\nORDER BY NameLength DESC, ProductName;`, need: ['d11', 'd06', 'd03b'], ok: ['d02'] });
  G('d11', 4, { p: (r, d) => ({ cat: r.pick(d.categories), dp: r.pick([0, 1]) }), ask: p => `For ${p.cat} products, show each name and its margin as a percentage of price, rounded to ${p.dp === 0 ? 'a whole number' : '1 decimal place'}. Biggest margin first.`, clue: p => `rounded to ${p.dp === 0 ? 'a whole number' : '1 decimal place'}`,
    sol: p => `SELECT ProductName,\n       ROUND((UnitPrice - UnitCost) / UnitPrice * 100, ${p.dp}) AS MarginPct\nFROM catalog.Products\nWHERE Category = ${q(p.cat)}\nORDER BY MarginPct DESC;`, need: ['d11', 'd06', 'd03b'], ok: ['d02'] });
  G('d11', 5, { p: (r, d) => ({ seg: r.pick(d.segments) }), ask: p => `Which email providers do our ${p.seg} customers use? For each one with an email, show the name and the part after the @, in small letters (some emails were typed in capitals).`, clue: () => ['the part after the @', 'in small letters'],
    sol: p => `SELECT CustomerName,\n       LOWER(SUBSTRING(Email, CHARINDEX('@', Email) + 1, LEN(Email))) AS Provider\nFROM crm.Customers\nWHERE Email IS NOT NULL\n  AND CustomerSegment = ${q(p.seg)};`, need: ['d11', 'd07'], ok: ['d02', 'd06'] });

  // ───────── d12 · Date Parts
  G('d12', 1, { p: r => r.pick([{ k: 'ym' }, { k: 'mn' }]), ask: p => (p.k === 'ym' ? 'Show each order’s ID with the year and the month number it was placed in, as two separate columns.' : 'Show each order’s ID, its date, and the name of the month it was placed in (like “March”).'), clue: p => (p.k === 'ym' ? 'as two separate columns' : 'the name of the month'),
    sol: p => (p.k === 'ym' ? `SELECT OrderID, YEAR(OrderDate) AS OrderYear, MONTH(OrderDate) AS OrderMonth\nFROM sales.Orders;` : `SELECT OrderID, OrderDate, DATENAME(month, OrderDate) AS MonthName\nFROM sales.Orders;`), ok: ['d02'] });
  G('d12', 2, { p: r => r.pick([{ k: 'hire' }, { k: 'join' }]), ask: p => (p.k === 'hire' ? 'For each employee, show their name and the year they were hired.' : 'For each customer, show their name and which quarter of the year they joined in (1 to 4).'), clue: p => (p.k === 'hire' ? 'the year they were hired' : 'which quarter of the year'),
    sol: p => (p.k === 'hire' ? `SELECT EmployeeName, YEAR(HireDate) AS HireYear\nFROM hr.Employees;` : `SELECT CustomerName, DATEPART(quarter, JoinDate) AS JoinQuarter\nFROM crm.Customers;`), ok: ['d02'] });
  G('d12', 3, { p: (r, d) => ({ m: r.pick(d.months) }), ask: p => `Which orders were placed in ${p.m.name}? Order ID and date, oldest first (lower ID first on the same day).`, clue: p => `in ${p.m.name}`,
    sol: p => `SELECT OrderID, OrderDate\nFROM sales.Orders\nWHERE YEAR(OrderDate) = ${p.m.y}\n  AND MONTH(OrderDate) = ${p.m.m}\nORDER BY OrderDate, OrderID;`, need: ['d12', 'd06', 'd03b'], ok: ['d02', 'd07'] });
  G('d12', 4, { p: r => ({ day: r.pick(['Saturday', 'Sunday', 'Monday', 'Friday']), y: r.pick([2024, 2025]) }), ask: p => `How busy are ${p.day}s? List the ${p.y} orders placed on a ${p.day}: order ID, date and channel.`, clue: p => `on a ${p.day}`,
    sol: p => `SELECT OrderID, OrderDate, Channel\nFROM sales.Orders\nWHERE DATENAME(weekday, OrderDate) = ${q(p.day)}\n  AND YEAR(OrderDate) = ${p.y};`, need: ['d12', 'd06'], ok: ['d02'] });
  G('d12', 5, { p: r => ({ m: r.int(1, 12) }), ask: p => `Who joined us in ${util.MONTHS[p.m - 1]}, in any year? Name, join date and join year, earliest first.`, clue: p => `in ${util.MONTHS[p.m - 1]}, in any year`,
    sol: p => `SELECT CustomerName, JoinDate, YEAR(JoinDate) AS JoinYear\nFROM crm.Customers\nWHERE MONTH(JoinDate) = ${p.m}\nORDER BY JoinDate;`, need: ['d12', 'd06', 'd03b'], ok: ['d02'] });

  // ───────── d13 · DATEADD · DATEDIFF
  G('d13', 1, { p: (r, d) => ({ m: r.pick(d.months) }), ask: p => `For delivered orders placed in ${p.m.name}, how many days did each take to ship? Order ID, order date, shipped date and days.`, clue: p => 'how many days did each take',
    sol: p => `SELECT OrderID, OrderDate, ShippedDate,\n       DATEDIFF(day, OrderDate, ShippedDate) AS DaysToShip\nFROM sales.Orders\nWHERE Status = 'Delivered'\n  AND OrderDate >= '${p.m.start}' AND OrderDate < '${p.m.next}';`, ok: ['d02', 'd06'] });
  G('d13', 2, { p: r => ({ n: r.pick([7, 10, 14, 21, 30]) }), ask: p => `Which orders came in during the last ${p.n} days? (Today is 30 June 2025.) Order ID and date. Count today as day 0, so an order exactly ${p.n} days ago counts.`, clue: p => `the last ${p.n} days`,
    sol: p => `SELECT OrderID, OrderDate\nFROM sales.Orders\nWHERE OrderDate >= DATEADD(day, -${p.n}, CAST(GETDATE() AS date));`, ok: ['d02', 'd06'] });
  G('d13', 3, { p: r => ({ n: r.pick([3, 5]), pr: r.pick(['High', 'Medium', 'Low']) }), ask: p => `Which ${p.n} resolved ${p.pr}-priority tickets took the longest, in hours? Ticket ID and hours, longest first.`, clue: p => 'took the longest, in hours',
    sol: p => `SELECT TOP (${p.n}) TicketID,\n       DATEDIFF(hour, OpenedDate, ResolvedDate) AS HoursOpen\nFROM support.Tickets\nWHERE ResolvedDate IS NOT NULL\n  AND Priority = ${q(p.pr)}\nORDER BY HoursOpen DESC;`, need: ['d13', 'd06', 'd03b'], ok: ['d02', 'd07'] });
  G('d13', 4, { p: r => ({ n: r.pick([14, 18, 21, 25]) }), ask: p => `Returns must arrive within ${p.n} days of the order. Which returns came later than that? Return ID, order date, return date and the days between.`, clue: p => `within ${p.n} days of the order`,
    sol: p => `SELECT r.ReturnID, o.OrderDate, r.ReturnDate,\n       DATEDIFF(day, o.OrderDate, r.ReturnDate) AS DaysLater\nFROM sales.Returns r\nJOIN sales.Orders o ON o.OrderID = r.OrderID\nWHERE DATEDIFF(day, o.OrderDate, r.ReturnDate) > ${p.n};`, need: ['d13', 'd08', 'd06'], ok: ['d02'], min: 1 });
  G('d13', 5, { p: r => ({ y: r.pick([1, 2]) }), ask: p => `Who has been with us for more than ${p.y} year${p.y > 1 ? 's' : ''} (today is 30 June 2025)? Name, join date and the number of whole months they’ve been with us, longest first.`, clue: p => `more than ${p.y} year`,
    sol: p => `SELECT CustomerName, JoinDate,\n       DATEDIFF(month, JoinDate, GETDATE()) AS MonthsWithUs\nFROM crm.Customers\nWHERE JoinDate < DATEADD(year, -${p.y}, CAST(GETDATE() AS date))\nORDER BY JoinDate;`, need: ['d13', 'd06', 'd03b'], ok: ['d02'] });

  // ───────── d14 · NULL Logic
  G('d14', 1, { p: r => r.pick([{ c: 'Email', w: 'email' }, { c: 'Phone', w: 'phone number' }]), ask: p => `How many customers do we have, and how many of them have a ${p.w} on file? Two numbers in one row.`, clue: p => `have a ${p.w} on file`, need: ['d14'],
    sol: p => `SELECT COUNT(*) AS Customers, COUNT(${p.c}) AS With${p.c}\nFROM crm.Customers;`, why: () => 'COUNT(*) counts rows; COUNT(column) skips the NULLs. Side by side, they show what’s missing.', ok: ['d02'] });
  G('d14', 2, { p: r => r.pick([{ k: 'ship' }, { k: 'open' }]), ask: p => (p.k === 'ship' ? 'Which orders haven’t been shipped yet (there’s no shipped date)? Order ID, date and status.' : 'Which support tickets haven’t been resolved yet (no resolved date)? Ticket ID, opened date and priority.'), clue: p => (p.k === 'ship' ? 'there’s no shipped date' : 'no resolved date'),
    sol: p => (p.k === 'ship' ? `SELECT OrderID, OrderDate, Status\nFROM sales.Orders\nWHERE ShippedDate IS NULL;` : `SELECT TicketID, OpenedDate, Priority\nFROM support.Tickets\nWHERE ResolvedDate IS NULL;`), ok: ['d02', 'd07'] });
  G('d14', 3, { p: (r, d) => ({ ch: r.pick(d.channels), n: r.pick([5, 8]) }), ask: p => `Show the ${p.n} most recent ${p.ch} orders that did get a discount: order ID, date and discount amount, newest first (higher ID first on the same day).`, clue: p => 'did get a discount',
    sol: p => `SELECT TOP (${p.n}) OrderID, OrderDate, DiscountAmount\nFROM sales.Orders\nWHERE DiscountAmount IS NOT NULL\n  AND Channel = ${q(p.ch)}\nORDER BY OrderDate DESC, OrderID DESC;`, need: ['d14', 'd06', 'd03b'], ok: ['d02', 'd07'] });
  G('d14', 4, { p: r => ({ pr: r.pick(['High', 'Medium']) }), ask: p => `Which ${p.pr}-priority tickets are still waiting for a resolution? Ticket ID, customer ID and opened date, oldest first.`, clue: p => 'still waiting for a resolution',
    sol: p => `SELECT TicketID, CustomerID, OpenedDate\nFROM support.Tickets\nWHERE ResolvedDate IS NULL\n  AND Priority = ${q(p.pr)}\nORDER BY OpenedDate;`, need: ['d14', 'd06', 'd03b'], ok: ['d02', 'd07'], min: 1 });
  G('d14', 5, { p: r => r.pick([{ c: 'ShippedDate', a: 'Shipped', b: 'NotShipped', w: 'how many orders have shipped and how many haven’t' }, { c: 'DiscountAmount', a: 'Discounted', b: 'NotDiscounted', w: 'how many orders got a discount and how many didn’t' }]),
    ask: p => `In one row, show ${p.w}.`, clue: p => p.w, sol: p => `SELECT COUNT(${p.c}) AS ${p.a},\n       COUNT(*) - COUNT(${p.c}) AS ${p.b}\nFROM sales.Orders;`, ok: ['d02'] });

  // ───────── d15 · ISNULL · COALESCE
  G('d15', 1, { p: r => r.pick([{ c: 'Email', s: 'no email' }, { c: 'Phone', s: 'no phone' }]), ask: p => `List every customer’s name and ${p.c.toLowerCase()}, but where it’s missing show “${p.s}” instead.`, clue: p => `show “${p.s}” instead`,
    sol: p => `SELECT CustomerName, ISNULL(${p.c}, ${q(p.s)}) AS ${p.c}\nFROM crm.Customers;`, ok: ['d02'] });
  G('d15', 2, { p: (r, d) => ({ ch: r.pick(['Web', 'Mobile']) }), ask: p => `For every ${p.ch} order, show the order ID, the shipping fee, the discount (show 0 where there was none), and the fee minus the discount.`, clue: () => 'show 0 where there was none',
    sol: p => `SELECT OrderID, ShippingFee,\n       ISNULL(DiscountAmount, 0) AS Discount,\n       ShippingFee - ISNULL(DiscountAmount, 0) AS NetFee\nFROM sales.Orders\nWHERE Channel = ${q(p.ch)};`, ok: ['d02', 'd14', 'd06'], why: () => 'Fee minus a NULL discount is NULL. ISNULL turns the missing discount into 0 first.' });
  G('d15', 3, { p: (r, d) => ({ city: r.pick(d.cities) }), ask: p => `For customers in ${p.city}, give me one way to reach each: their email, or their phone if there’s no email, or “no contact” if there’s neither. Name and contact, A to Z.`, clue: p => 'or their phone if there’s no email',
    sol: p => `SELECT CustomerName,\n       COALESCE(Email, Phone, 'no contact') AS Contact\nFROM crm.Customers\nWHERE City = ${q(p.city)}\nORDER BY CustomerName;`, need: ['d15', 'd06', 'd03b'], ok: ['d02'] });
  G('d15', 4, { p: r => ({ ch: r.pick(['Email', 'Phone', 'Chat']) }), ask: p => `For tickets that came in by ${p.ch}, show the ticket ID, status, and the resolution notes, or “still open” where there are none yet. Newest ticket first.`, clue: p => '“still open” where there are none',
    sol: p => `SELECT TicketID, Status,\n       ISNULL(ResolutionNotes, 'still open') AS Notes\nFROM support.Tickets\nWHERE ContactChannel = ${q(p.ch)}\nORDER BY OpenedDate DESC;`, need: ['d15', 'd06', 'd03b'], ok: ['d02'] });
  G('d15', 5, { p: (r, d) => ({ m: r.pick(d.months25), ch: r.pick(['Web', 'Mobile']) }), ask: p => `For ${p.ch} orders in ${p.m.name}: order ID, the shipping fee, and the discount as a share of the fee (discount ÷ fee). Treat a missing discount as 0, and avoid dividing by zero where the fee is 0 by showing NULL.`, clue: p => ['Treat a missing discount as 0', 'avoid dividing by zero'],
    sol: p => `SELECT OrderID, ShippingFee,\n       ISNULL(DiscountAmount, 0) / NULLIF(ShippingFee, 0) AS DiscountShare\nFROM sales.Orders\nWHERE Channel = ${q(p.ch)}\n  AND OrderDate >= '${p.m.start}' AND OrderDate < '${p.m.next}';`, need: ['d15', 'd06'], ok: ['d02', 'd14'] });

  // ───────── d16a · CASE
  G('d16a', 1, { p: r => { const a = r.pick([20, 25]); return { a, b: a + r.pick([20, 25, 30]) }; }, ask: p => `Label every product by price: under ${money(p.a)} is “Budget”, under ${money(p.b)} is “Mid”, and anything else is “Premium”. Name, price and label.`, clue: p => 'Label every product by price',
    sol: p => `SELECT ProductName, UnitPrice,\n       CASE\n         WHEN UnitPrice < ${p.a} THEN 'Budget'\n         WHEN UnitPrice < ${p.b} THEN 'Mid'\n         ELSE 'Premium'\n       END AS PriceBand\nFROM catalog.Products;`, ok: ['d02'] });
  G('d16a', 2, { p: r => r.pick([{ k: 'ch' }, { k: 'act' }]), ask: p => (p.k === 'ch' ? 'For every order, show the ID and a label: “In person” for Store orders, “Online” for everything else.' : 'For every customer, show the name and “Active” or “Inactive”, based on the IsActive flag (1 or 0).'), clue: p => (p.k === 'ch' ? '“In person” for Store orders' : '“Active” or “Inactive”'),
    sol: p => (p.k === 'ch' ? `SELECT OrderID,\n       CASE WHEN Channel = 'Store' THEN 'In person' ELSE 'Online' END AS HowBought\nFROM sales.Orders;` : `SELECT CustomerName,\n       CASE WHEN IsActive = 1 THEN 'Active' ELSE 'Inactive' END AS Standing\nFROM crm.Customers;`), ok: ['d02'] });
  G('d16a', 3, { p: (r, d) => ({ m: r.pick(d.months) }), ask: p => `For orders placed in ${p.m.name}, show the order ID, status and a shipping label: “Not shipped” if there’s no shipped date, “Fast” if it shipped within 2 days of the order, otherwise “Standard”. Oldest first (lower ID first on the same day).`, clue: p => ['“Not shipped” if there’s no shipped date', '“Fast” if it shipped within 2 days'],
    sol: p => `SELECT OrderID, Status,\n       CASE\n         WHEN ShippedDate IS NULL THEN 'Not shipped'\n         WHEN DATEDIFF(day, OrderDate, ShippedDate) <= 2 THEN 'Fast'\n         ELSE 'Standard'\n       END AS Speed\nFROM sales.Orders\nWHERE OrderDate >= '${p.m.start}' AND OrderDate < '${p.m.next}'\nORDER BY OrderDate, OrderID;`, need: ['d16a', 'd06', 'd13', 'd03b'], ok: ['d02', 'd14', 'd07'] });
  G('d16a', 4, { p: (r, d) => ({ city: r.pick(d.cities) }), ask: p => `For customers in ${p.city}, show the name and a “tenure” label: “Since 2022” for anyone who joined before 2023, “Since 2023–24” for 2023 or 2024, and “New” for 2025 joiners. Earliest joiner first.`, clue: p => 'a “tenure” label',
    sol: p => `SELECT CustomerName,\n       CASE\n         WHEN JoinDate < '2023-01-01' THEN 'Since 2022'\n         WHEN JoinDate < '2025-01-01' THEN 'Since 2023–24'\n         ELSE 'New'\n       END AS Tenure\nFROM crm.Customers\nWHERE City = ${q(p.city)}\nORDER BY JoinDate;`, need: ['d16a', 'd06', 'd03b'], ok: ['d02', 'd12'] });
  G('d16a', 5, { p: r => ({ y: r.pick([2024, 2025]) }), ask: p => `For resolved tickets opened in ${p.y}, show the ticket ID, priority and a speed label: “Same day” if resolved within 8 hours, “Next day” within 24 hours, otherwise “Slow”. Slowest first.`, clue: () => 'a speed label',
    sol: p => `SELECT TicketID, Priority,\n       CASE\n         WHEN DATEDIFF(hour, OpenedDate, ResolvedDate) <= 8 THEN 'Same day'\n         WHEN DATEDIFF(hour, OpenedDate, ResolvedDate) <= 24 THEN 'Next day'\n         ELSE 'Slow'\n       END AS Speed\nFROM support.Tickets\nWHERE ResolvedDate IS NOT NULL\n  AND YEAR(OpenedDate) = ${p.y}\nORDER BY DATEDIFF(hour, OpenedDate, ResolvedDate) DESC;`, need: ['d16a', 'd13', 'd06'], ok: ['d02', 'd12', 'd14', 'd03b'], ordered: false });

  // ───────── d16b · GROUP BY & HAVING
  G('d16b', 1, { p: r => r.pick([{ c: 'Category', t: 'catalog.Products', w: 'How many products do we have in each category?' }, { c: 'City', t: 'crm.Customers', w: 'How many customers live in each city?' }, { c: 'Channel', t: 'sales.Orders', w: 'How many orders came through each channel?' }, { c: 'Department', t: 'hr.Employees', w: 'How many people work in each department?' }, { c: 'ReturnReason', t: 'sales.Returns', w: 'How many returns were there for each reason?' }]),
    ask: p => p.w, clue: p => p.w.match(/in each \w+|for each \w+|through each \w+/)[0], sol: p => `SELECT ${p.c}, COUNT(*) AS Total\nFROM ${p.t}\nGROUP BY ${p.c};`, ok: ['d02'], distract: ['d06', 'd03a'] });
  G('d16b', 2, { p: r => r.pick([{ g: 'Category', w: 'product category' }, { g: 'CustomerSegment', w: 'customer segment' }, { g: 'Channel', w: 'channel' }]), ask: p => `What’s our total revenue by ${p.w}? Use the sales detail view’s LineRevenue.`, clue: p => `total revenue by ${p.w}`,
    sol: p => `SELECT ${p.g}, SUM(LineRevenue) AS Revenue\nFROM reporting.vSalesLineDetail\nGROUP BY ${p.g};`, ok: ['d02'] });
  G('d16b', 3, { p: (r, d) => ({ ch: r.pick(d.channels), y: r.pick([2024, 2025]) }), ask: p => `For ${p.ch} orders placed in ${p.y}, how many are in each status?`, clue: p => 'how many are in each status',
    sol: p => `SELECT Status, COUNT(*) AS Orders\nFROM sales.Orders\nWHERE Channel = ${q(p.ch)}\n  AND OrderDate >= '${p.y}-01-01' AND OrderDate < '${p.y + 1}-01-01'\nGROUP BY Status;`, need: ['d16b', 'd06'], ok: ['d02', 'd12'], why: () => 'WHERE trims the rows first (only that channel and year), then GROUP BY makes the piles.' });
  G('d16b', 4, { p: r => r.pick([{ k: 'cust', n: r.pick([12, 14, 16]) }, { k: 'city', n: 4 }]), ask: p => (p.k === 'cust' ? `Which customers have placed at least ${p.n} orders? Customer ID and number of orders, most first.` : `Which cities have at least ${p.n} customers? City and count.`), clue: p => `at least ${p.n}`,
    sol: p => (p.k === 'cust' ? `SELECT CustomerID, COUNT(*) AS Orders\nFROM sales.Orders\nGROUP BY CustomerID\nHAVING COUNT(*) >= ${p.n}\nORDER BY Orders DESC;` : `SELECT City, COUNT(*) AS Customers\nFROM crm.Customers\nGROUP BY City\nHAVING COUNT(*) >= ${p.n};`), need: ['d16b'], ok: ['d02', 'd03b'], why: () => '“At least n” is a filter on a count, and counts only exist after grouping, so it goes in HAVING, not WHERE.' });
  G('d16b', 5, { p: r => ({ y: r.pick([2024, 2025]), n: r.pick([3000, 4000, 5000]) }), ask: p => `Which customer segments brought in more than ${money(p.n)} in ${p.y}? Segment and revenue, highest first. Ignore cancelled orders.`, clue: p => ['Ignore cancelled orders', `more than ${money(p.n)}`],
    sol: p => `SELECT CustomerSegment, SUM(LineRevenue) AS Revenue\nFROM reporting.vSalesLineDetail\nWHERE Status <> 'Cancelled'\n  AND OrderDate >= '${p.y}-01-01' AND OrderDate < '${p.y + 1}-01-01'\nGROUP BY CustomerSegment\nHAVING SUM(LineRevenue) > ${p.n}\nORDER BY Revenue DESC;`, need: ['d16b', 'd06', 'd03b'], ok: ['d02', 'd12'] });
})();
